const body = $("panel/amenities/sync").first().json.body || {};
const centerId = body.center_id;
const rawIds = body.amenity_ids;

// Supports two input shapes:
// 1) amenity_ids: [1, 2, 3]  -> no note
// 2) amenity_ids: [{ id: 1, note: "..." }, { id: 2 }]  -> optional per-item note
const items = Array.isArray(rawIds) ? rawIds : [];

const normalized = items
  .map((it) => {
    if (it && typeof it === "object") {
      const id = Number(it.id ?? it.amenity_id);
      const note = it.note != null ? String(it.note).slice(0, 255) : null;
      return { id, note };
    }
    return { id: Number(it), note: null };
  })
  .filter((it) => Boolean(it.id));

if (normalized.length === 0) {
  return [{
    json: {
      center_id: centerId,
      amenity_id: null,
      note: null
    }
  }];
}

return normalized.map((it) => ({
  json: {
    center_id: centerId,
    amenity_id: it.id,
    note: it.note
  }
}));

